const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

class ParseError extends Error {
  constructor(message) {
    super(message)
    this.name = 'ParseError'
  }
}

/**
 * Parses the raw stdin text into a graph description:
 *   { tasks: Map<name, cost>, deps: Map<name, string[]>, depRefs: [{name, line}] }
 * `deps` holds, for every task, the deduplicated list of dependency names in
 * the order first seen. `depRefs` records every (dependency-name, line)
 * pair in the order encountered, used to report the first unknown
 * reference in input order.
 * Throws ParseError with a message already formatted (without the
 * `error: ` prefix) on any malformed line.
 */
export function parseGraph(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const tasks = new Map()
  const deps = new Map()
  const depRefs = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new ParseError(`line ${lineNo}: expected task <name> <cost>`)
      }
      const [, name, cost] = words
      if (!NAME_RE.test(name)) {
        throw new ParseError(`line ${lineNo}: invalid task name ${name}`)
      }
      if (!COST_RE.test(cost)) {
        throw new ParseError(`line ${lineNo}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw new ParseError(`line ${lineNo}: task ${name} is declared twice`)
      }
      tasks.set(name, parseInt(cost, 10))
      if (!deps.has(name)) deps.set(name, [])
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new ParseError(`line ${lineNo}: expected dep <name> <dependency>...`)
      }
      const rest = words.slice(1)
      for (const word of rest) {
        if (!NAME_RE.test(word)) {
          throw new ParseError(`line ${lineNo}: invalid task name ${word}`)
        }
      }
      const [name, ...dependencies] = rest
      if (!deps.has(name)) deps.set(name, [])
      const list = deps.get(name)
      for (const dep of dependencies) {
        depRefs.push({ name: dep, line: lineNo })
        if (!list.includes(dep)) list.push(dep)
      }
    } else {
      throw new ParseError(`line ${lineNo}: unknown directive ${directive}`)
    }
  }

  // Every name referenced by a dep line must be declared by a task line.
  for (const ref of depRefs) {
    if (!tasks.has(ref.name)) {
      throw new ParseError(`unknown task ${ref.name}`)
    }
  }

  return { tasks, deps }
}

