{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-haiku-vs-sonnet-t5/cell-RA0MYh/src/graph.js","content":"// Graph algorithms shared by the three cli modes: cycle detection, wave
// depth, timing (start/finish) and pack-priority (longest downstream chain).

class CycleError extends Error {
  constructor(cycleNames) {
    super(`cycle: ${cycleNames.join(' -> ')}`)
    this.name = 'CycleError'
    this.cycleNames = cycleNames
  }
}

/**
 * Detects a cycle by running a DFS from each task in ascending name order,
 * walking each task's dependencies in ascending name order. Returns the
 * first cycle found as an array of names starting and ending at the
 * re-entered task, or null when the graph is acyclic.
 */
export function findCycle(tasks, deps) {
  const names = [...tasks.keys()].sort()
  const state = new Map() // 0 = unvisited, 1 = on stack, 2 = done
  const stack = []

  function dfs(name) {
    state.set(name, 1)
    stack.push(name)
    const dependencies = [...(deps.get(name) || [])].sort()
    for (const dep of dependencies) {
      const st = state.get(dep)
      if (st === 1) {
        const idx = stack.indexOf(dep)
        const cyclePath = stack.slice(idx)
        cyclePath.push(dep)
        return cyclePath
      } else if (st !== 2) {
        const found = dfs(dep)
        if (found) return found
      }
    }
    stack.pop()
    state.set(name, 2)
    return null
  }

  for (const name of names) {
    if (!state.has(name)) {
      const found = dfs(name)
      if (found) return found
    }
  }
  return null
}

/**
 * Computes, for every task, its depth (wave number), start and finish
 * times under an unlimited number of workers.
 * Returns { depth: Map, start: Map, finish: Map, total }.
 */
export function computeTiming(tasks, deps) {
  const depth = new Map()
  const start = new Map()
  const finish = new Map()

  function compute(name) {
    if (finish.has(name)) return
    const dependencies = deps.get(name) || []
    let d = 0
    let s = 0
    for (const dep of dependencies) {
      compute(dep)
      d = Math.max(d, depth.get(dep) + 1)
      s = Math.max(s, finish.get(dep))
    }
    depth.set(name, d)
    start.set(name, s)
    finish.set(name, s + tasks.get(name))
  }

  for (const name of tasks.keys()) compute(name)

  let total = 0
  for (const f of finish.values()) total = Math.max(total, f)

  return { depth, start, finish, total }
}

/**
 * Computes, for every task, the priority used by `pack`: the cost of the
 * longest chain of costs starting at the task and continuing through
 * tasks that depend on it, ending at a task nothing depends on.
 */
export function computePriority(tasks, deps) {
  const successors = new Map()
  for (const name of tasks.keys()) successors.set(name, [])
  for (const [name, dependencies] of deps.entries()) {
    for (const dep of dependencies) {
      if (!successors.has(dep)) successors.set(dep, [])
      successors.get(dep).push(name)
    }
  }

  const priority = new Map()
  function compute(name) {
    if (priority.has(name)) return priority.get(name)
    let best = 0
    for (const succ of successors.get(name) || []) {
      best = Math.max(best, compute(succ))
    }
    const p = tasks.get(name) + best
    priority.set(name, p)
    return p
  }

  for (const name of tasks.keys()) compute(name)
  return priority
}

export { CycleError }
"}

