      const startT = time
      const endT = time + cost
      assigned.add(best)
      finishTime.set(best, endT)
      workerBusyUntil[workerIdx] = endT
      assignments[workerIdx].push({ name: best, start: startT, finish: endT })
      doneCount++
    }

    if (doneCount >= total) break

    let next = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (workerBusyUntil[i] > time) next = Math.min(next, workerBusyUntil[i])
    }
    if (next === Infinity) {
