/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { parseGraph, ParseError } from './parse.js'
import { findCycle, computeTiming, computePriority } from './graph.js'
import { pack } from './pack.js'

function usageError() {
  process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n')
  process.exit(2)
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  const fs = require('node:fs')
  try {
    return fs.readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main() {
  const args = process.argv.slice(2)

  let mode
  let workerCount = null

  if (args.length === 1 && (args[0] === 'waves' || args[0] === 'explain')) {
    mode = args[0]
  } else if (args.length === 2 && args[0] === 'pack') {
    mode = 'pack'
    const w = args[1]
    if (!/^[1-9][0-9]*$/.test(w)) {
      fail('workers must be a positive integer')
    }
    workerCount = parseInt(w, 10)
  } else {
    usageError()
  }

  const input = readStdin()

  let graph
  try {
    graph = parseGraph(input)
  } catch (err) {
    if (err instanceof ParseError) {
      fail(err.message)
    }
    throw err
  }

  const { tasks, deps } = graph

  const cycle = findCycle(tasks, deps)
  if (cycle) {
    process.stderr.write(`error: cycle: ${cycle.join(' -> ')}\n`)
    process.exit(3)
  }

  if (mode === 'waves') {
    const { depth, total } = computeTiming(tasks, deps)
    const waves = new Map()
    for (const [name, d] of depth.entries()) {
      if (!waves.has(d)) waves.set(d, [])
      waves.get(d).push(name)
    }
    const maxDepth = waves.size === 0 ? -1 : Math.max(...waves.keys())
    let out = ''
    for (let k = 0; k <= maxDepth; k++) {
      const names = (waves.get(k) || []).sort()
      out += `wave ${k}: ${names.join(' ')}\n`
    }
    out += `total ${total}\n`
    process.stdout.write(out)
  } else if (mode === 'explain') {
    const { depth, start, finish, total } = computeTiming(tasks, deps)
    const names = [...tasks.keys()].sort()
    let out = ''
    for (const name of names) {
      out += `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}\n`
    }
    out += `total ${total}\n`
    process.stdout.write(out)
  } else if (mode === 'pack') {
    const priority = computePriority(tasks, deps)
    const { assignments, makespan } = pack(tasks, deps, priority, workerCount)
    let out = ''
    for (let i = 0; i < workerCount; i++) {
      const parts = assignments[i].map((t) => ` ${t.name}@${t.start}-${t.finish}`).join('')
      out += `worker ${i}:${parts}\n`
    }
    out += `makespan ${makespan}\n`
    process.stdout.write(out)
  }
}

main()
"}

